import Foundation
struct Viewers { let streamID: Int; let revision: Int; let count: Int }
protocol ViewerSource { func fetchSnapshot() -> Viewers }
struct LocalViewerSource: ViewerSource {
    let value: Viewers
    func fetchSnapshot() -> Viewers { value }
}
func poll(
    source: any ViewerSource, ticks: Int
) -> [Viewers] {
    var rows: [Viewers] = []
    for _ in 0..<max(0, ticks) { rows.append(source.fetchSnapshot()) }
    return rows
}
let source = LocalViewerSource(
    value: Viewers(streamID: 4, revision: 2, count: 30)
)
print(poll(source: source, ticks: 2).count)
print(poll(source: source, ticks: -1).count)

Вывод 2, 0. Polling запрашивает снимки по ритму вызывающего кода; это не непрерывный серверный поток.

