struct ServiceQueueState {
    let queueID: Int
    var revision = 0
    var waiting = 0
    mutating func accept(_ value: QueueSnapshot) {
        guard value.queueID == queueID, value.revision != revision else {
            return
        }
        revision = value.revision
        waiting = value.waiting
    }
}
